/* PsicoMoodle — estudos dirigidos da revisão final de 2026/2.
   Questões didáticas autorais fundamentadas nos tópicos de estudo já cadastrados.
   Roteiros originais dos professores são preservados separadamente. */
(()=>{
'use strict';
const TARGETS=['tcc','meta','grupos','social','avaliacao'];
function makeQuestion(topic,i){
 const scenario=String(topic.scenario||'Analise como o conceito se aplica a uma situação real, respeitando o contexto.').trim();
 const idea=String(topic.definition||'').trim();
 const myth=String(topic.myth||'').trim();
 return {n:i+1,topic:topic.title,section:'Revisão por assunto',
 question:'Explique '+topic.title+'.\n\nSituação: '+scenario+'\n\nComo esse conceito ajuda a entender o caso? O que ainda seria preciso saber antes de concluir?',
 options:[],answer:null,
 explanation:'Definição: '+idea+'\n\nSituação para análise: '+scenario+'\n\nUse os fatos do caso para explicar o conceito. Pense também em outras explicações possíveis. Um exemplo sozinho não permite concluir um diagnóstico ou uma causa.',
 contrast:(myth?'Evite a interpretação simplista: '+myth+'\n\n':'')+'Diferencie o que aconteceu, como o caso pode ser explicado e o que poderia ser feito.',
 points:[
 {title:'Definição do conceito',explanation:idea,example:''},
 {title:'Aplicação ao cenário',explanation:'Identifique fatos relevantes da situação e relacione-os ao conceito sem ignorar outras explicações plausíveis.',example:scenario},
 {title:'Limites e conclusão',explanation:'Considere a ética, as condições sociais e o contexto. Um exemplo isolado não basta para definir um diagnóstico ou uma causa.',example:''}
 ]};
}
const FAMILY_P2_GUIDE={"id":"familia-p2-revisao-conferida-2026","title":"Revisão comentada — Psicologia da Família (P2)","subtitle":"30 questões autorais alinhadas às aulas posteriores à P1","source":"Revisão autoral baseada no Cronograma Psicologia da Família 2026/2, aulas de 16/09 a 23/11, com P2 marcada para 25/11, e nos temas dos materiais da disciplina. As perguntas e respostas não foram atribuídas à professora e não representam gabarito oficial.","status":"adaptado","questions":[{"n":1,"section":"Divórcio e mudanças familiares","topic":"Divórcio e parentalidade","question":"Após o divórcio, o que muda na rotina da família? Quais responsabilidades dos pais continuam?","explanation":"O término de uma união conjugal não elimina as responsabilidades parentais. Há mudanças em moradia, rotinas, apoio financeiro, regras de convivência e comunicação entre responsáveis. A qualidade da reorganização depende da situação concreta, dos recursos da família, da proteção dos filhos e da capacidade de separar conflitos conjugais das tarefas de cuidado. É preciso reconhecer que configurações diversas podem oferecer vínculos seguros.","contrast":"Não presumir que todo divórcio provoque dano psicológico. O conflito persistente, a exposição de crianças a disputas e a falta de apoio merecem avaliação específica.","options":[],"answer":null},{"n":2,"section":"Divórcio e mudanças familiares","topic":"Triangulação e lealdades","question":"Na separação, os pais pedem que a criança escolha um lado. O que é triangulação e como isso pode afetá-la?","explanation":"A triangulação ocorre quando uma terceira pessoa é colocada em um conflito entre duas outras, assumindo posições de mensageiro, aliado ou mediador. A criança pode vivenciar conflito de lealdade e sentir que demonstrar afeto por um responsável significa trair o outro. Uma intervenção cuidadosa preserva sua segurança e a retira de responsabilidades que cabem aos adultos, favorecendo acordos parentais mais previsíveis.","contrast":"Não interpretar qualquer preferência da criança como manipulação. O contexto, a idade, a segurança e eventuais situações de violência precisam ser considerados.","options":[],"answer":null},{"n":3,"section":"Divórcio e mudanças familiares","topic":"Adaptação pós-separação","question":"O que ajuda uma família a se adaptar ao divórcio? O que pode dificultar essa adaptação?","explanation":"São importantes a previsibilidade das rotinas, a comunicação apropriada à idade dos filhos, a redução de conflitos entre adultos e o acesso a redes de apoio. Dificuldades econômicas, isolamento, mudanças frequentes e conflitos persistentes podem ampliar a sobrecarga. O psicólogo investiga essas condições sem presumir uma sequência obrigatória de reações ou um único modelo de família saudável.","contrast":"Não confundir existência de conflitos com problemas inevitáveis. A análise deve levar em conta a duração, a intensidade e o contexto dos conflitos.","options":[],"answer":null},{"n":4,"section":"Famílias monoparentais e recasadas","topic":"Monoparentalidade","question":"O que caracteriza uma família monoparental? Por que ela não deve ser vista como incompleta?","explanation":"Famílias monoparentais são organizadas em torno de um responsável e seus filhos ou dependentes, com possibilidades variadas de participação da família extensa e da rede de cuidado. Podem surgir por escolha, separação, morte ou outras circunstâncias. Não há déficit psicológico inerente a essa configuração; as necessidades concretas dependem de renda, tempo disponível, vínculos, apoio social e proteção.","contrast":"Evitar associar monoparentalidade à ausência de cuidado por definição. A qualidade das relações não pode ser deduzida apenas do número de responsáveis.","options":[],"answer":null},{"n":5,"section":"Famílias monoparentais e recasadas","topic":"Famílias reconstituídas","question":"Quais dificuldades podem surgir em uma família recasada?","explanation":"Novas relações podem exigir negociações sobre moradia, regras, papéis, autoridade, convivência e vínculos com familiares de uniões anteriores. Crianças e adultos podem precisar de tempos diferentes para construir confiança. A reorganização pode ser facilitada por comunicação clara, reconhecimento dos vínculos preexistentes e expectativas realistas sobre aproximação afetiva.","contrast":"Não supor que o novo companheiro ou companheira substitui imediatamente outro responsável, nem forçar afeto ou autoridade sem considerar a história dos vínculos.","options":[],"answer":null},{"n":6,"section":"Famílias monoparentais e recasadas","topic":"Fronteiras e lealdades","question":"Como podem surgir conflitos de lealdade em uma família recasada? Como lidar com os limites de cada pessoa?","explanation":"Um filho pode recear que aceitar o novo parceiro de um responsável signifique magoar o outro. A leitura sistêmica investiga alianças, papéis, comunicação e fronteiras entre subsistemas sem atribuir culpa exclusivamente à criança. A intervenção pode favorecer diálogo e responsabilidades claras entre adultos, reconhecendo que a aproximação afetiva requer tempo e respeito.","contrast":"Evitar classificar resistência inicial como patologia ou rejeição definitiva. Considerar também a segurança dos envolvidos e possíveis situações de violência.","options":[],"answer":null},{"n":7,"section":"Diversidade sexual e de gênero","topic":"Diversidade familiar","question":"Como o psicólogo deve lidar com diferentes orientações sexuais e identidades de gênero nas famílias?","explanation":"A composição da família não se limita a um arranjo heterossexual ou a papéis rígidos de gênero. Devem ser considerados vínculos, responsabilidades de cuidado, direitos, reconhecimento e contexto sociocultural. A prática psicológica não patologiza orientações sexuais nem identidades de gênero e busca compreender as demandas concretas das pessoas, inclusive os efeitos de discriminação e barreiras institucionais.","contrast":"Não transformar diferenças familiares em indicadores automáticos de disfuncionalidade. Preconceito externo pode afetar os vínculos sem definir o funcionamento de todas as famílias.","options":[],"answer":null},{"n":8,"section":"Diversidade sexual e de gênero","topic":"Revelação e acolhimento","question":"Uma pessoa fala sobre sua orientação sexual ou identidade de gênero com a família. O que deve ser considerado no acolhimento?","explanation":"A avaliação inclui segurança, qualidade dos vínculos, recursos de apoio, possíveis reações discriminatórias e autonomia da pessoa. Familiares podem precisar de informação e diálogo, mas isso não autoriza coerção ou tentativas de mudar a identidade ou orientação. O cuidado deve garantir escuta, proteção e respeito à privacidade, com encaminhamentos apropriados se houver risco.","contrast":"Não impor a revelação a familiares ou terceiros como condição de atendimento. A avaliação de riscos e a autonomia precisam orientar as decisões.","options":[],"answer":null},{"n":9,"section":"Adoção e segredos","topic":"Adoção e pertencimento","question":"O que o psicólogo precisa considerar sobre a história e os vínculos de uma família formada pela adoção?","explanation":"Adoção envolve pertencimento, reconhecimento, identidade e vínculos construídos no cotidiano. O profissional considera a história anterior da criança ou adolescente, seus recursos, os vínculos existentes e como a família responde às questões sobre origem e pertencimento. Nenhum comportamento pode ser explicado automaticamente pela adoção; é necessário investigar as condições reais de cuidado e desenvolvimento.","contrast":"Não supor que pessoas adotadas tenham necessariamente problemas de vínculo ou identidade. Evitar determinismos e estigmas.","options":[],"answer":null},{"n":10,"section":"Adoção e segredos","topic":"Segredo e privacidade","question":"Qual é a diferença entre privacidade e segredo familiar? Dê um exemplo ligado à adoção.","explanation":"Privacidade protege informações pessoais e limites legítimos de exposição. Um segredo familiar pode produzir dificuldades quando organiza proibições de falar, versões contraditórias da história, alianças e medos que afetam a confiança. O tema da origem adotiva exige comunicação sensível ao desenvolvimento e às necessidades da pessoa, sem tratar a revelação como um ato obrigatório e abrupto.","contrast":"Nem todo segredo é patológico, nem toda revelação melhora os vínculos automaticamente. O que importa é a função do silêncio e seus efeitos nas relações.","options":[],"answer":null},{"n":11,"section":"Adoção e segredos","topic":"Segredos nas relações","question":"Como um segredo mantido pela família pode afetar a comunicação e a relação entre seus membros?","explanation":"Silêncios persistentes podem aparecer em evasivas, tensões, alianças e assuntos proibidos, influenciando expectativas entre gerações. A abordagem relacional investiga quem conhece a informação, por que a mantém e quais efeitos ela produz, sem inferir a existência de segredos a partir de sintomas isolados. Segurança, consentimento e limites éticos orientam qualquer proposta de diálogo.","contrast":"Não utilizar técnicas para forçar confissões nem presumir que toda dificuldade relacional decorra de um segredo oculto.","options":[],"answer":null},{"n":12,"section":"Violência intrafamiliar e abuso sexual","topic":"Formas de violência","question":"Qual é a diferença entre conflito familiar e violência intrafamiliar? Cite formas de violência.","explanation":"Conflitos envolvem diferenças e tensões que não necessariamente incluem violação de direitos. Violência pode abranger agressões físicas, humilhações, ameaças, controle coercitivo, abuso sexual e outras práticas que geram dano e assimetria de poder. A proximidade familiar pode dificultar a busca de apoio por dependência, medo e lealdades. A prioridade profissional é reconhecer riscos e construir condições de proteção.","contrast":"Não tratar situações de coerção e abuso como divergências simétricas entre duas partes. Isso pode invisibilizar responsabilidades.","options":[],"answer":null},{"n":13,"section":"Violência intrafamiliar e abuso sexual","topic":"Proteção de crianças","question":"Como o psicólogo deve agir quando suspeita de violência contra uma criança ou adolescente?","explanation":"É necessário acolher relatos com respeito, avaliar a segurança, distinguir fatos observados de hipóteses e seguir fluxos profissionais de proteção. A atuação deve relacionar a rede competente, conforme contexto e deveres de comunicação. Perguntas sugestivas e entrevistas repetidas sem finalidade justificada podem ampliar sofrimento ou comprometer procedimentos adequados. Nenhum sinal isolado confirma ou exclui violência.","contrast":"Evitar produzir conclusões periciais a partir de um comportamento isolado ou assumir sozinho uma investigação para a qual não haja competência e respaldo técnico.","options":[],"answer":null},{"n":14,"section":"Violência intrafamiliar e abuso sexual","topic":"Abuso sexual e poder","question":"Por que é importante considerar as relações de poder e o silêncio em casos de abuso sexual na família?","explanation":"Em situações de abuso sexual, dependência, vínculo afetivo, ameaça e diferenças de poder podem dificultar o reconhecimento e a revelação. A análise psicossocial precisa priorizar a segurança e evitar responsabilizar vítimas. O trabalho pode exigir relação com saúde, assistência e órgãos de proteção, respeitando papéis profissionais distintos e a necessidade de não revitimizar a pessoa atendida.","contrast":"Não equiparar abuso a uma relação consentida entre iguais, nem propor reconciliação como solução automática para violência.","options":[],"answer":null},{"n":15,"section":"Violência intrafamiliar e abuso sexual","topic":"Acolhimento sem revitimização","question":"Como acolher alguém que relata violência familiar sem aumentar seu sofrimento?","explanation":"A escuta deve ser não julgadora, com linguagem acessível e explicitação dos limites de sigilo e das responsabilidades profissionais. É importante avaliar riscos, registrar informações com clareza e acionar redes de proteção quando cabível. O cuidado reconhece a autonomia da pessoa na medida de suas possibilidades e evita que precise repetir desnecessariamente relatos traumáticos.","contrast":"Não pressionar por detalhes irrelevantes nem confrontar a vítima com o suposto agressor em condições inseguras.","options":[],"answer":null},{"n":16,"section":"Violência intrafamiliar e abuso sexual","topic":"Pobreza e negligência","question":"Por que pobreza e falta de recursos não são, por si só, sinais de negligência familiar?","explanation":"A falta de recursos pode limitar o acesso a cuidados e serviços sem indicar, por si só, desinteresse pelos filhos. Uma avaliação responsável investiga condições materiais, possibilidades reais de cuidado, apoio disponível e violações concretas. A relação com a assistência social pode ser essencial para reduzir riscos e fortalecer vínculos, sem culpabilizar a família por desigualdades estruturais.","contrast":"Não equiparar pobreza a negligência. Também não se pode ignorar um risco real para crianças sob o argumento de que a família enfrenta dificuldades econômicas.","options":[],"answer":null},{"n":17,"section":"Luto e reorganização familiar","topic":"Luto e diversidade","question":"Por que o luto não acontece necessariamente em etapas fixas?","explanation":"As reações à perda variam conforme vínculos, circunstâncias, cultura, história e apoio disponível. Tristeza, raiva, saudade, alívio e momentos de aparente normalidade podem coexistir, sem ordem universal. O acompanhamento considera os significados da perda e as condições de vida da pessoa, evitando converter toda reação distinta em sintoma patológico.","contrast":"Não exigir que alguém atravesse cinco fases predefinidas, nem usar a ausência de choro como prova de que não houve sofrimento.","options":[],"answer":null},{"n":18,"section":"Luto e reorganização familiar","topic":"Mudanças de papéis","question":"Como uma morte pode mudar os papéis, as responsabilidades e os vínculos da família?","explanation":"A perda de um integrante pode alterar cuidado, recursos financeiros, papéis de autoridade, rotinas e comunicação. Os membros podem reagir de formas distintas e precisar de apoio em tempos diferentes. Rituais e memórias podem manter vínculos simbólicos, enquanto a família constrói novas formas de organização. O trabalho psicológico busca compreender as necessidades e os recursos disponíveis.","contrast":"Reorganização não é substituição da pessoa que morreu. Preservar a memória da relação pode coexistir com mudanças concretas na família.","options":[],"answer":null},{"n":19,"section":"Luto e reorganização familiar","topic":"Luto na infância","question":"Uma criança faz muitas perguntas após a morte de alguém próximo. Como os adultos podem acolhê-la?","explanation":"É útil oferecer explicações honestas e adequadas ao desenvolvimento, reconhecer sentimentos e preservar rotinas protetivas quando possível. A criança pode expressar seu sofrimento por fala, brincadeiras ou mudanças de comportamento; perguntas reiteradas podem ajudá-la a compreender a perda. A família também pode precisar de apoio para cuidar da criança enquanto vivencia seu próprio luto.","contrast":"Não impor explicações universais ou exigir que a criança demonstre tristeza nos mesmos termos de um adulto.","options":[],"answer":null},{"n":20,"section":"Famílias e uso problemático de substâncias","topic":"Impactos relacionais","question":"Como o uso problemático de álcool ou outras drogas pode afetar as relações familiares?","explanation":"O uso pode afetar previsibilidade das rotinas, cuidados, confiança, comunicação, finanças e responsabilidades. A perspectiva sistêmica considera como cada integrante responde ao problema e quais recursos de apoio existem, mas não atribui à família a culpa pelo uso de substâncias. O cuidado integra necessidades individuais, segurança de dependentes e acesso a serviços apropriados.","contrast":"Não reduzir todos os vínculos familiares à dependência química nem responsabilizar outros membros pela recuperação de uma pessoa.","options":[],"answer":null},{"n":21,"section":"Famílias e uso problemático de substâncias","topic":"Sobrecarga e proteção","question":"Um familiar tenta esconder o uso problemático de substâncias de outra pessoa. O que o psicólogo precisa investigar?","explanation":"Esse comportamento pode tentar evitar conflitos imediatos ou proteger outras pessoas, mas também pode aumentar sobrecarga e dificultar a busca de ajuda. O psicólogo investiga o contexto, os riscos, a segurança e as redes disponíveis antes de formular hipóteses. Podem ser construídas formas mais adequadas de apoio, comunicação e divisão de responsabilidades, respeitando a autonomia dos envolvidos.","contrast":"Não rotular automaticamente o familiar como codependente nem presumir que punições, isoladamente, resolvam uma situação complexa.","options":[],"answer":null},{"n":22,"section":"Famílias e uso problemático de substâncias","topic":"Segurança de dependentes","question":"Quais cuidados devem ser prioridade quando há crianças em uma família afetada pelo uso problemático de substâncias?","explanation":"É importante verificar condições reais de supervisão, segurança, alimentação, cuidado emocional e presença de adultos confiáveis. A existência de uso por um integrante não prova incapacidade parental; a análise deve identificar riscos observáveis e recursos de proteção. Quando necessário, a rede de saúde e proteção social precisa ser mobilizada de forma coordenada.","contrast":"Evitar tanto estigmatizar a família quanto minimizar riscos imediatos que possam comprometer crianças e dependentes.","options":[],"answer":null},{"n":23,"section":"Atendimento familiar em diferentes contextos","topic":"Atendimento clínico","question":"Quais são os primeiros cuidados no atendimento psicológico de uma família?","explanation":"O trabalho procura compreender demandas, padrões relacionais, recursos e dificuldades, definindo objetivos e condições dos encontros. É importante esclarecer quem participa, como as informações serão manejadas e os limites de sigilo. Hipóteses sobre o sistema familiar não anulam responsabilidades individuais, principalmente em situações de violência. A indicação de encontros conjuntos depende da segurança e do contexto.","contrast":"Não procurar automaticamente um integrante culpado ou transformar a teoria sistêmica em justificativa para neutralizar a gravidade de abusos.","options":[],"answer":null},{"n":24,"section":"Atendimento familiar em diferentes contextos","topic":"Atendimento hospitalar","question":"Como o psicólogo pode apoiar uma família durante uma doença grave ou internação?","explanation":"O cuidado pode apoiar a comunicação, a elaboração de mudanças de rotina e papéis, a compreensão de informações dentro dos limites éticos e o acolhimento do sofrimento. A atuação se articula à equipe multiprofissional e reconhece a autonomia da pessoa hospitalizada, sua privacidade e as necessidades de cuidadores. Também pode ser relevante em perdas e tratamentos prolongados.","contrast":"Não supor que qualquer familiar tem direito a todas as informações clínicas, nem ignorar os desejos e direitos do paciente.","options":[],"answer":null},{"n":25,"section":"Atendimento familiar em diferentes contextos","topic":"Atendimento escolar","question":"Uma escola culpa a estrutura familiar pelas dificuldades de um aluno. Como o psicólogo deve avaliar a situação?","explanation":"É preciso considerar o contexto escolar, condições de ensino, desenvolvimento, relações e recursos da família, sem supor causalidade a partir de uma configuração específica. O profissional pode construir diálogo com responsáveis e educadores e promover ações compatíveis com a finalidade do trabalho, preservando sigilo e evitando estigmas sobre famílias diversas.","contrast":"Não confundir correlação com causa, nem usar a expressão 'família desestruturada' como explicação técnica suficiente.","options":[],"answer":null},{"n":26,"section":"Atendimento familiar em diferentes contextos","topic":"Contexto jurídico","question":"Qual é a diferença entre atender famílias na clínica e no contexto jurídico?","explanation":"A atuação no sistema de justiça pode envolver avaliação, orientação técnica ou perícia, segundo finalidades e atribuições delimitadas. Exige procedimentos adequados, atenção aos direitos dos envolvidos, fontes de informação proporcionais e comunicação de limites das conclusões. Isso não significa, por si só, psicoterapia familiar; objetivos e deveres profissionais variam conforme a demanda institucional.","contrast":"Não emitir conclusões sobre vínculos familiares com base em preferências pessoais ou em informações insuficientes.","options":[],"answer":null},{"n":27,"section":"Atendimento familiar em diferentes contextos","topic":"Assistência social","question":"Qual é o papel do atendimento psicológico a famílias na assistência social?","explanation":"Esse contexto enfatiza direitos, acesso a serviços, redes de apoio, vulnerabilidades do território e fortalecimento de vínculos. O psicólogo considera fatores estruturais e recursos comunitários em relação com equipes e políticas públicas, evitando reduzir dificuldades sociais a características individuais. Quando necessário, são construídos encaminhamentos junto a serviços de saúde, educação e proteção.","contrast":"Não confundir pobreza com falha moral da família, nem substituir ações de garantia de direitos por diagnósticos psicológicos sem fundamento.","options":[],"answer":null},{"n":28,"section":"Questões integradoras da P2","topic":"Caso: divórcio e recasamento","question":"Uma adolescente acha que gostar do padrasto é trair o pai. Como entender esse conflito com os conceitos da disciplina?","explanation":"O caso mobiliza temas de divórcio, recasamento, lealdades e limites entre papéis familiares. Pode haver conflito de lealdade, mas essa hipótese precisa ser investigada por meio da escuta e do contexto. A intervenção busca reduzir exigências de tomada de partido, reconhecer a história dos vínculos e favorecer acordos de convivência respeitosos. O objetivo é proteger a autonomia afetiva da adolescente.","contrast":"Não atribuir o problema somente à adolescente nem forçar aproximação afetiva para provar que o recasamento foi bem-sucedido.","options":[],"answer":null},{"n":29,"section":"Questões integradoras da P2","topic":"Caso: proteção e cuidado","question":"Uma família vive conflitos, uso problemático de substâncias e suspeita de violência contra uma criança. Qual deve ser a prioridade?","explanation":"A prioridade é verificar e promover segurança e proteção, mobilizando serviços competentes e respeitando protocolos profissionais. O cuidado com o uso de substâncias pode exigir acompanhamento especializado, mas não substitui respostas a situações de violência. Uma leitura sistêmica considera padrões relacionais e redes disponíveis sem distribuir igualmente a responsabilidade por agressões. A intervenção deve reduzir revitimização e garantir atenção às necessidades da criança.","contrast":"Não propor reconciliação imediata ou terapia conjunta como solução automática quando houver riscos de violência.","options":[],"answer":null},{"n":30,"section":"Questões integradoras da P2","topic":"Caso: luto e hospital","question":"Após uma morte, os familiares reagem de formas diferentes. Como o psicólogo deve acolher essas diferenças?","explanation":"O psicólogo pode acolher reações distintas, identificar necessidades individuais e ajudar na comunicação familiar, respeitando diferentes tempos de elaboração. A perda pode alterar papéis e responsabilidades e coexistir com rituais e memórias que preservam o pertencimento. No contexto hospitalar, é essencial relacionar ações com a equipe e respeitar limites de informação e a autonomia das pessoas envolvidas.","contrast":"Não classificar uma reação como correta e outra como errada apenas porque uma pessoa chora e outra permanece silenciosa.","options":[],"answer":null}]};
const GRUPOS_P2_GUIDE={"id":"grupos-p2-revisao-conferida-2026","title":"Estudo dirigido — Rogers, Moreno e Escritores da Liberdade (P2)","subtitle":"43 questões comentadas de teoria e aplicação ao filme","source":"Slides de Psicodrama e Carl Rogers; Almeida, O que é Psicodrama; Rogers, Grupos de Encontro, caps. 1 e 2; filme Escritores da Liberdade (2007). Roteiro autoral, não gabarito do professor.","status":"adaptado","questions":[{"n":1,"section":"Moreno — fundamentos","topic":"Origens: teatro da espontaneidade","question":"Exemplo teórico: em um grupo psicodramático, uma pessoa recria uma conversa difícil e experimenta outra maneira de agir. A aula de Erin não é uma sessão de psicodrama.\n\nPor que a ação é central no psicodrama?","options":[],"answer":null,"explanation":"Porque permite explorar papéis e vínculos em uma cena vivida no presente e experimentar outras respostas, com condução e elaboração.","points":[{"title":"Conceito","explanation":"Moreno partiu de experiências com ação, teatro e relações sociais. O psicodrama utiliza a dramatização para explorar como as pessoas agem, sentem e se vinculam, em vez de apenas relatar acontecimentos.","example":""},{"title":"Aplicação","explanation":"Porque permite explorar papéis e vínculos em uma cena vivida no presente e experimentar outras respostas, com condução e elaboração.","example":"Exemplo teórico: em um grupo psicodramático, uma pessoa recria uma conversa difícil e experimenta outra maneira de agir. A aula de Erin não é uma sessão de psicodrama."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":2,"section":"Moreno — fundamentos","topic":"Espontaneidade: resposta adequada e nova","question":"Cena: no tribunal, Eva decide identificar o verdadeiro responsável pelo crime, contrariando a expectativa de proteger Paco. A resposta rompe uma lealdade rígida e considera as consequências para o inocente.\n\nComo o depoimento de Eva ilustra espontaneidade?","options":[],"answer":null,"explanation":"Ela encontra uma resposta nova e adequada diante de uma situação marcada por expectativas antigas de lealdade. Não se trata de agir por impulso.","points":[{"title":"Conceito","explanation":"Espontaneidade, para Moreno, não é agir sem pensar ou de maneira impulsiva. É a capacidade de responder de modo novo e apropriado a uma situação, superando roteiros rígidos.","example":""},{"title":"Aplicação","explanation":"Ela encontra uma resposta nova e adequada diante de uma situação marcada por expectativas antigas de lealdade. Não se trata de agir por impulso.","example":"Cena: no tribunal, Eva decide identificar o verdadeiro responsável pelo crime, contrariando a expectativa de proteger Paco. A resposta rompe uma lealdade rígida e considera as consequências para o inocente."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":3,"section":"Moreno — fundamentos","topic":"Criatividade e relação com a espontaneidade","question":"Cena: os alunos propõem trazer Miep Gies à escola e organizam a arrecadação. Criam uma possibilidade concreta de encontro que não existia no roteiro inicial da aula.\n\nComo distinguir criatividade e espontaneidade nesse projeto?","options":[],"answer":null,"explanation":"A espontaneidade mobiliza uma resposta adequada à situação; a criatividade produz a nova possibilidade, como organizar a arrecadação e o encontro.","points":[{"title":"Conceito","explanation":"A criatividade diz respeito à produção de possibilidades e respostas novas; a espontaneidade mobiliza essa criação na situação vivida. Os dois conceitos são relacionados, mas não idênticos.","example":""},{"title":"Aplicação","explanation":"A espontaneidade mobiliza uma resposta adequada à situação; a criatividade produz a nova possibilidade, como organizar a arrecadação e o encontro.","example":"Cena: os alunos propõem trazer Miep Gies à escola e organizam a arrecadação. Criam uma possibilidade concreta de encontro que não existia no roteiro inicial da aula."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":4,"section":"Moreno — fundamentos","topic":"Conserva cultural e repetição de papéis","question":"Cena: Eva aprende, em seu grupo de pertencimento, que deve defender os seus mesmo diante de uma injustiça. Essa regra condiciona o depoimento esperado dela.\n\nO que a regra de lealdade ilustra para Moreno?","options":[],"answer":null,"explanation":"Uma conserva cultural: um padrão transmitido e cristalizado que, quando rigidamente repetido, limita respostas novas. A lealdade em si não é necessariamente prejudicial.","points":[{"title":"Conceito","explanation":"Conserva cultural é um produto ou padrão já estabilizado, criado no passado e transmitido socialmente. Pode preservar conquistas, mas tornar-se rígida e inibir respostas criativas quando tratada como única possibilidade.","example":""},{"title":"Aplicação","explanation":"Uma conserva cultural: um padrão transmitido e cristalizado que, quando rigidamente repetido, limita respostas novas. A lealdade em si não é necessariamente prejudicial.","example":"Cena: Eva aprende, em seu grupo de pertencimento, que deve defender os seus mesmo diante de uma injustiça. Essa regra condiciona o depoimento esperado dela."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":5,"section":"Moreno — papéis e vínculos","topic":"Papel social: agir numa relação","question":"Cena: Marcus procura a mãe e manifesta o desejo de retornar para casa. Sua relação como filho volta a ocupar espaço ao lado de outras possibilidades de vida.\n\nComo a história de Marcus ajuda a compreender a teoria dos papéis?","options":[],"answer":null,"explanation":"Os papéis existem nas relações e podem se reorganizar. O papel ligado à gangue não esgota a identidade de Marcus; ele pode reconstruir a relação como filho.","points":[{"title":"Conceito","explanation":"Papel não é uma essência fixa da personalidade; é uma forma de atuar em situações e relações concretas. Um mesmo participante pode exercer papéis diferentes conforme o grupo, a situação e os vínculos.","example":""},{"title":"Aplicação","explanation":"Os papéis existem nas relações e podem se reorganizar. O papel ligado à gangue não esgota a identidade de Marcus; ele pode reconstruir a relação como filho.","example":"Cena: Marcus procura a mãe e manifesta o desejo de retornar para casa. Sua relação como filho volta a ocupar espaço ao lado de outras possibilidades de vida."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":6,"section":"Moreno — papéis e vínculos","topic":"Tomada, desempenho e criação de papéis","question":"Exemplo teórico: assumir um papel segundo um modelo aprendido, desempenhá-lo com alguma flexibilidade e criar uma maneira própria de exercê-lo são possibilidades distintas. O filme permite pensar a ampliação de repertórios, não identificar essas etapas como protocolo.\n\nDiferencie tomada, desempenho e criação de papéis.","options":[],"answer":null,"explanation":"Tomada é assumir um modelo de papel; desempenho envolve exercê-lo com alguma flexibilidade; criação envolve produzir formas novas de atuação.","points":[{"title":"Conceito","explanation":"A formação de papéis pode envolver assumir modelos já conhecidos, desempenhá-los numa relação e criar formas novas de exercê-los. A aprendizagem não é apenas imitação: pode abrir espaço à transformação.","example":""},{"title":"Aplicação","explanation":"Tomada é assumir um modelo de papel; desempenho envolve exercê-lo com alguma flexibilidade; criação envolve produzir formas novas de atuação.","example":"Exemplo teórico: assumir um papel segundo um modelo aprendido, desempenhá-lo com alguma flexibilidade e criar uma maneira própria de exercê-lo são possibilidades distintas. O filme permite pensar a ampliação de repertórios, não identificar essas etapas como protocolo."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":7,"section":"Moreno — papéis e vínculos","topic":"Sociometria: escolhas, rejeições e reciprocidades","question":"Cena: no começo, a turma se distribui segundo pertencimentos e rivalidades. É possível observar aproximações e rejeições, mas não há um teste sociométrico com critério de escolha explícito.\n\nO que seria necessário para investigar sociometricamente os vínculos da turma?","options":[],"answer":null,"explanation":"Definir um critério concreto de escolha, como com quem realizar uma tarefa, coletar escolhas dos participantes e analisar reciprocidades e rejeições. A disposição das carteiras não basta.","points":[{"title":"Conceito","explanation":"Sociometria investiga sistematicamente atrações, rejeições e escolhas segundo critérios definidos, para compreender a estrutura de vínculos de um grupo. Não basta observar quem está sentado junto ou quem discute.","example":""},{"title":"Aplicação","explanation":"Definir um critério concreto de escolha, como com quem realizar uma tarefa, coletar escolhas dos participantes e analisar reciprocidades e rejeições. A disposição das carteiras não basta.","example":"Cena: no começo, a turma se distribui segundo pertencimentos e rivalidades. É possível observar aproximações e rejeições, mas não há um teste sociométrico com critério de escolha explícito."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":8,"section":"Moreno — papéis e vínculos","topic":"Sociograma e configuração relacional","question":"Exemplo teórico: após perguntar a cada integrante com quem gostaria de trabalhar, representa-se cada pessoa por um ponto e as escolhas por setas. O gráfico mostra reciprocidades e isolamentos.\n\nPara que serve o sociograma?","options":[],"answer":null,"explanation":"Para representar visualmente os vínculos levantados por um procedimento sociométrico, permitindo examinar escolhas, reciprocidades e posições na rede.","points":[{"title":"Conceito","explanation":"Sociograma é uma representação gráfica de relações sociométricas obtidas por procedimento de escolha; pode revelar reciprocidades, isolamento, concentrações e interligações sob um critério específico.","example":""},{"title":"Aplicação","explanation":"Para representar visualmente os vínculos levantados por um procedimento sociométrico, permitindo examinar escolhas, reciprocidades e posições na rede.","example":"Exemplo teórico: após perguntar a cada integrante com quem gostaria de trabalhar, representa-se cada pessoa por um ponto e as escolhas por setas. O gráfico mostra reciprocidades e isolamentos."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":9,"section":"Moreno — papéis e vínculos","topic":"Tele: percepção e reciprocidade no encontro","question":"Cena: no jogo da linha, estudantes de grupos rivais percebem que compartilham experiências de perda e observam uns aos outros. Essa mudança oferece condições para uma percepção mais recíproca, mas não comprova tele positiva entre todos.\n\nComo relacionar o jogo da linha à tele sem confundi-la com empatia?","options":[],"answer":null,"explanation":"A tele envolve a dimensão afetiva e recíproca da relação. Reconhecer o outro e ser reconhecido pode transformar atrações e rejeições; empatia é compreender a perspectiva alheia.","points":[{"title":"Conceito","explanation":"Tele descreve a dimensão relacional de percepção e vínculo recíproco, e não se reduz a simpatia unilateral. Envolve a possibilidade de perceber o outro no encontro, em vez de agir apenas por fantasias e estereótipos.","example":""},{"title":"Aplicação","explanation":"A tele envolve a dimensão afetiva e recíproca da relação. Reconhecer o outro e ser reconhecido pode transformar atrações e rejeições; empatia é compreender a perspectiva alheia.","example":"Cena: no jogo da linha, estudantes de grupos rivais percebem que compartilham experiências de perda e observam uns aos outros. Essa mudança oferece condições para uma percepção mais recíproca, mas não comprova tele positiva entre todos."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":10,"section":"Moreno — papéis e vínculos","topic":"Átomo social e rede afetiva","question":"Cena: Marcus está afastado da mãe e vinculado a colegas da gangue; quando busca a mãe e se aproxima da turma, sua rede significativa se reorganiza. Trata-se de uma leitura conceitual, não de um levantamento formal.\n\nO que significa átomo social?","options":[],"answer":null,"explanation":"É o conjunto de relações afetivamente significativas que situam a pessoa em sua rede social. A análise considera vínculos, proximidades e distâncias.","points":[{"title":"Conceito","explanation":"O átomo social se refere ao conjunto significativo de relações afetivas que organiza a posição de uma pessoa em sua rede, considerando proximidades e distâncias vividas.","example":""},{"title":"Aplicação","explanation":"É o conjunto de relações afetivamente significativas que situam a pessoa em sua rede social. A análise considera vínculos, proximidades e distâncias.","example":"Cena: Marcus está afastado da mãe e vinculado a colegas da gangue; quando busca a mãe e se aproxima da turma, sua rede significativa se reorganiza. Trata-se de uma leitura conceitual, não de um levantamento formal."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":11,"section":"Moreno — técnicas e método","topic":"Psicodrama e sociodrama: focos diferentes","question":"Exemplo teórico: uma pessoa dramatiza uma conversa familiar para explorar seu mundo relacional; um grupo dramatiza um conflito entre papéis sociais para examinar discriminação. A primeira proposta pode ser psicodrama, a segunda sociodrama.\n\nQual é a diferença central entre psicodrama e sociodrama?","options":[],"answer":null,"explanation":"O psicodrama privilegia o drama e as relações do protagonista; o sociodrama privilegia a questão coletiva, as relações intergrupais e os papéis sociais.","points":[{"title":"Conceito","explanation":"No psicodrama, a dramatização pode centrar-se na experiência e nos papéis de um protagonista, articulados ao grupo. O sociodrama trabalha papéis e conflitos coletivos ligados a um tema compartilhado.","example":""},{"title":"Aplicação","explanation":"O psicodrama privilegia o drama e as relações do protagonista; o sociodrama privilegia a questão coletiva, as relações intergrupais e os papéis sociais.","example":"Exemplo teórico: uma pessoa dramatiza uma conversa familiar para explorar seu mundo relacional; um grupo dramatiza um conflito entre papéis sociais para examinar discriminação. A primeira proposta pode ser psicodrama, a segunda sociodrama."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":12,"section":"Moreno — técnicas e método","topic":"Aquecimento: preparo para a ação","question":"Cena: no jogo da linha, Erin começa com perguntas cotidianas e gradualmente aborda vivências significativas. Movimento, participação e reconhecimento mútuo mobilizam a turma. É uma analogia com o aquecimento, não uma sessão formal.\n\nEm que sentido a dinâmica da linha se aproxima do aquecimento inespecífico?","options":[],"answer":null,"explanation":"Ela mobiliza o grupo por meio da ação e favorece a disponibilidade para reconhecer experiências comuns. O aquecimento específico prepararia um tema e uma cena para dramatização.","points":[{"title":"Conceito","explanation":"É a etapa que prepara participantes e contexto para o trabalho dramático, favorecendo disponibilidade, segurança e definição do foco. Não é só um jogo para quebrar o gelo.","example":""},{"title":"Aplicação","explanation":"Ela mobiliza o grupo por meio da ação e favorece a disponibilidade para reconhecer experiências comuns. O aquecimento específico prepararia um tema e uma cena para dramatização.","example":"Cena: no jogo da linha, Erin começa com perguntas cotidianas e gradualmente aborda vivências significativas. Movimento, participação e reconhecimento mútuo mobilizam a turma. É uma analogia com o aquecimento, não uma sessão formal."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":13,"section":"Moreno — técnicas e método","topic":"Dramatização: ação no aqui-agora","question":"Exemplo teórico: uma participante representa uma conversa difícil no palco psicodramático e explora respostas possíveis com apoio do diretor e dos egos auxiliares.\n\nO que diferencia dramatização de simplesmente narrar um conflito?","options":[],"answer":null,"explanation":"O conflito é colocado em ação no espaço do como se, permitindo vivenciar papéis, afetos e novas respostas no presente.","points":[{"title":"Conceito","explanation":"Na dramatização, a situação é explorada por meio de ação, cenas e papéis, com acompanhamento do diretor e dos demais elementos do método. Não é teatro para apresentar um espetáculo ao público.","example":""},{"title":"Aplicação","explanation":"O conflito é colocado em ação no espaço do como se, permitindo vivenciar papéis, afetos e novas respostas no presente.","example":"Exemplo teórico: uma participante representa uma conversa difícil no palco psicodramático e explora respostas possíveis com apoio do diretor e dos egos auxiliares."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":14,"section":"Moreno — técnicas e método","topic":"Compartilhamento: elaborar sem julgamento","question":"Exemplo teórico: depois de uma cena psicodramática, integrantes relatam como foram tocados pelo vivido, sem dar conselhos obrigatórios. O brinde do filme lembra a partilha de experiências, mas não é o compartilhamento técnico após dramatização.\n\nQual é a função do compartilhamento?","options":[],"answer":null,"explanation":"Elaborar a experiência da dramatização por meio das ressonâncias pessoais do grupo, acolhendo o protagonista sem julgamentos nem interpretações impostas.","points":[{"title":"Conceito","explanation":"Depois da dramatização, participantes compartilham ressonâncias e sentimentos ligados ao vivido, sem transformar o momento em interrogatório, conselho obrigatório ou julgamento do protagonista.","example":""},{"title":"Aplicação","explanation":"Elaborar a experiência da dramatização por meio das ressonâncias pessoais do grupo, acolhendo o protagonista sem julgamentos nem interpretações impostas.","example":"Exemplo teórico: depois de uma cena psicodramática, integrantes relatam como foram tocados pelo vivido, sem dar conselhos obrigatórios. O brinde do filme lembra a partilha de experiências, mas não é o compartilhamento técnico após dramatização."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":15,"section":"Moreno — técnicas e método","topic":"Cinco elementos do psicodrama","question":"Exemplo teórico: o diretor conduz; o protagonista coloca o drama em cena; o ego auxiliar representa personagens; o cenário é o espaço de ação; o público acompanha e participa afetivamente.\n\nQuais são os cinco elementos do psicodrama e suas funções?","options":[],"answer":null,"explanation":"Diretor, protagonista, ego auxiliar, cenário e público. Cada um sustenta uma função específica na construção e elaboração da cena.","points":[{"title":"Conceito","explanation":"Os elementos clássicos são diretor, protagonista, ego-auxiliar, plateia/grupo e cenário/palco. Cada elemento tem função no processo e não se confunde com um papel teatral fixo.","example":""},{"title":"Aplicação","explanation":"Diretor, protagonista, ego auxiliar, cenário e público. Cada um sustenta uma função específica na construção e elaboração da cena.","example":"Exemplo teórico: o diretor conduz; o protagonista coloca o drama em cena; o ego auxiliar representa personagens; o cenário é o espaço de ação; o público acompanha e participa afetivamente."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":16,"section":"Moreno — técnicas e método","topic":"Inversão de papéis","question":"Exemplo teórico: durante uma dramatização, uma estudante troca de papel com quem representa sua mãe, passando a agir a partir dessa posição. Escutar uma história no filme não equivale a essa troca em cena.\n\nComo funciona a inversão de papéis?","options":[],"answer":null,"explanation":"Há troca de posições na dramatização para experimentar o vínculo a partir do papel do outro. É uma técnica de ação, não apenas um exercício de imaginação.","points":[{"title":"Conceito","explanation":"Na inversão de papéis, o protagonista experimenta o lugar de outra pessoa significativa na cena, explorando percepções e respostas no vínculo. Não se trata apenas de imaginar o sentimento do outro.","example":""},{"title":"Aplicação","explanation":"Há troca de posições na dramatização para experimentar o vínculo a partir do papel do outro. É uma técnica de ação, não apenas um exercício de imaginação.","example":"Exemplo teórico: durante uma dramatização, uma estudante troca de papel com quem representa sua mãe, passando a agir a partir dessa posição. Escutar uma história no filme não equivale a essa troca em cena."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":17,"section":"Moreno — técnicas e método","topic":"Duplo, espelho e solilóquio","question":"Exemplo teórico: no duplo, o ego auxiliar dá voz a um sentimento pouco formulado; no espelho, a pessoa observa seu papel representado por outra; no solilóquio, verbaliza pensamentos e afetos durante a ação.\n\nDiferencie duplo, espelho e solilóquio.","options":[],"answer":null,"explanation":"Duplo: auxilia na expressão do que está pouco formulado. Espelho: observa o próprio papel representado. Solilóquio: verbaliza o que pensa e sente na cena.","points":[{"title":"Conceito","explanation":"No duplo, ego-auxiliar pode dar voz a aspectos pouco expressos do protagonista; no espelho, ele observa outra pessoa representar seu papel; no solilóquio, verbaliza pensamentos e sentimentos ligados à ação.","example":""},{"title":"Aplicação","explanation":"Duplo: auxilia na expressão do que está pouco formulado. Espelho: observa o próprio papel representado. Solilóquio: verbaliza o que pensa e sente na cena.","example":"Exemplo teórico: no duplo, o ego auxiliar dá voz a um sentimento pouco formulado; no espelho, a pessoa observa seu papel representado por outra; no solilóquio, verbaliza pensamentos e afetos durante a ação."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":18,"section":"Moreno — aplicação","topic":"Limites éticos da intervenção dramática","question":"Exemplo teórico: antes de dramatizar uma vivência delicada, o diretor explica a proposta, verifica disponibilidade e garante possibilidade de interromper. Depois, promove elaboração.\n\nQuais cuidados sustentam uma intervenção psicodramática responsável?","options":[],"answer":null,"explanation":"Preparação, consentimento, respeito a limites, cuidado com exposição e elaboração após a ação; a participação não deve ser forçada.","points":[{"title":"Conceito","explanation":"Dramatizar conflitos pode mobilizar emoções intensas. O método exige cuidado com participação, preparo, confidencialidade, manejo da exposição e elaboração ao final.","example":""},{"title":"Aplicação","explanation":"Preparação, consentimento, respeito a limites, cuidado com exposição e elaboração após a ação; a participação não deve ser forçada.","example":"Exemplo teórico: antes de dramatizar uma vivência delicada, o diretor explica a proposta, verifica disponibilidade e garante possibilidade de interromper. Depois, promove elaboração."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":19,"section":"Rogers — fundamentos","topic":"Abordagem centrada na pessoa","question":"Cena: Erin propõe diários sobre as experiências dos alunos e oferece condições de escuta sem reduzir a pessoa a seu histórico escolar. A prática pedagógica ilustra atitudes facilitadoras.\n\nO que caracteriza a abordagem centrada na pessoa?","options":[],"answer":null,"explanation":"A confiança no potencial de desenvolvimento da pessoa e a oferta de relações marcadas por compreensão empática, congruência e aceitação positiva incondicional.","points":[{"title":"Conceito","explanation":"Rogers enfatiza o potencial de desenvolvimento da pessoa em relações que ofereçam compreensão, autenticidade e aceitação. Nos grupos, essas condições podem favorecer expressão e aprendizagem interpessoal.","example":""},{"title":"Aplicação","explanation":"A confiança no potencial de desenvolvimento da pessoa e a oferta de relações marcadas por compreensão empática, congruência e aceitação positiva incondicional.","example":"Cena: Erin propõe diários sobre as experiências dos alunos e oferece condições de escuta sem reduzir a pessoa a seu histórico escolar. A prática pedagógica ilustra atitudes facilitadoras."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":20,"section":"Rogers — condições facilitadoras","topic":"Compreensão empática","question":"Cena: os estudantes visitam o museu do Holocausto e escutam sobreviventes em um jantar. Podem compreender experiências de pessoas de outro contexto histórico sem afirmar que suas histórias são idênticas.\n\nComo o encontro com os sobreviventes ilustra compreensão empática?","options":[],"answer":null,"explanation":"A escuta procura compreender o vivido do outro a partir da perspectiva dele, reconhecendo sofrimentos e diferenças sem reduzir uma experiência à outra.","points":[{"title":"Conceito","explanation":"Empatia é tentar captar o mundo vivido do outro a partir de sua perspectiva, comunicando compreensão sem julgar ou presumir que se vive exatamente a mesma experiência.","example":""},{"title":"Aplicação","explanation":"A escuta procura compreender o vivido do outro a partir da perspectiva dele, reconhecendo sofrimentos e diferenças sem reduzir uma experiência à outra.","example":"Cena: os estudantes visitam o museu do Holocausto e escutam sobreviventes em um jantar. Podem compreender experiências de pessoas de outro contexto histórico sem afirmar que suas histórias são idênticas."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":21,"section":"Rogers — condições facilitadoras","topic":"Consideração positiva incondicional","question":"Cena: Erin distribui diários e permite que os alunos decidam se a professora poderá lê-los. Ela acolhe as experiências independentemente de elas corresponderem a expectativas escolares.\n\nComo os diários ilustram consideração positiva incondicional?","options":[],"answer":null,"explanation":"O valor da pessoa não depende da aprovação de seu relato ou de seu desempenho. O espaço de expressão respeita autonomia, sem significar aprovação de condutas violentas.","points":[{"title":"Conceito","explanation":"É reconhecer o valor da pessoa e acolher sua experiência sem fazer da aprovação do outro condição para escutá-la. Isso não implica tolerar violência, humilhação ou discriminação.","example":""},{"title":"Aplicação","explanation":"O valor da pessoa não depende da aprovação de seu relato ou de seu desempenho. O espaço de expressão respeita autonomia, sem significar aprovação de condutas violentas.","example":"Cena: Erin distribui diários e permite que os alunos decidam se a professora poderá lê-los. Ela acolhe as experiências independentemente de elas corresponderem a expectativas escolares."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":22,"section":"Rogers — condições facilitadoras","topic":"Congruência e autenticidade","question":"Exemplo teórico: um facilitador reconhece que ficou preocupado com uma interação e comunica isso de maneira respeitosa, em vez de fingir indiferença. Congruência envolve consciência e expressão coerente da experiência.\n\nO que significa congruência para Rogers?","options":[],"answer":null,"explanation":"Coerência entre a experiência vivida, sua consciência e a expressão autêntica na relação; não exige exposição integral de sentimentos.","points":[{"title":"Conceito","explanation":"Congruência é coerência entre experiência vivida, consciência e expressão responsável na relação. Não é exposição impulsiva nem obrigação de contar tudo.","example":""},{"title":"Aplicação","explanation":"Coerência entre a experiência vivida, sua consciência e a expressão autêntica na relação; não exige exposição integral de sentimentos.","example":"Exemplo teórico: um facilitador reconhece que ficou preocupado com uma interação e comunica isso de maneira respeitosa, em vez de fingir indiferença. Congruência envolve consciência e expressão coerente da experiência."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":23,"section":"Rogers — grupos de encontro","topic":"Grupos de Encontro: objetivos e formato","question":"Exemplo teórico: em um grupo de encontro, os integrantes participam da construção dos objetivos e o facilitador não impõe um roteiro rígido. A turma de Erin tem finalidade escolar e atividades planejadas.\n\nO que caracteriza um grupo de encontro?","options":[],"answer":null,"explanation":"Grupo relativamente pouco estruturado que favorece contato autêntico, consciência de si, expressão de sentimentos e feedback, com facilitação e autonomia.","points":[{"title":"Conceito","explanation":"São grupos relativamente pouco estruturados, que favorecem contato interpessoal, exploração de sentimentos, percepção de si e feedback. A direção do processo emerge da experiência e participação do grupo, com facilitação.","example":""},{"title":"Aplicação","explanation":"Grupo relativamente pouco estruturado que favorece contato autêntico, consciência de si, expressão de sentimentos e feedback, com facilitação e autonomia.","example":"Exemplo teórico: em um grupo de encontro, os integrantes participam da construção dos objetivos e o facilitador não impõe um roteiro rígido. A turma de Erin tem finalidade escolar e atividades planejadas."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":24,"section":"Rogers — grupos de encontro","topic":"Influência de Lewin e T-Groups","question":"Exemplo teórico: nos T-Groups, participantes observam como suas interações afetam o grupo. Rogers amplia a atenção à experiência pessoal, aos afetos e ao encontro interpessoal.\n\nQual a contribuição dos T-Groups para Rogers?","options":[],"answer":null,"explanation":"A observação da dinâmica e das interações grupais no presente; os grupos de encontro ampliam o foco no desenvolvimento pessoal e relacional.","points":[{"title":"Conceito","explanation":"Os T-Groups, ligados à tradição de Kurt Lewin, enfatizavam observar interações e o próprio processo grupal. Os Grupos de Encontro ampliam o foco na experiência pessoal e na autenticidade relacional.","example":""},{"title":"Aplicação","explanation":"A observação da dinâmica e das interações grupais no presente; os grupos de encontro ampliam o foco no desenvolvimento pessoal e relacional.","example":"Exemplo teórico: nos T-Groups, participantes observam como suas interações afetam o grupo. Rogers amplia a atenção à experiência pessoal, aos afetos e ao encontro interpessoal."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":25,"section":"Rogers — processo grupal","topic":"Milling around: hesitação inicial","question":"Exemplo teórico: em um grupo pouco estruturado, os participantes conversam superficialmente e perguntam quem dará as orientações. Isso ilustra os rodeios iniciais descritos por Rogers.\n\nO que é milling around?","options":[],"answer":null,"explanation":"Momento inicial de hesitação, rodeios e busca de direção externa, associado à incerteza diante de um grupo relativamente não estruturado.","points":[{"title":"Conceito","explanation":"Rogers descreve no início do processo um movimento de rodeios, falas superficiais e dúvidas sobre quem conduz. Num grupo pouco estruturado, a ansiedade pode aumentar antes de surgir confiança.","example":""},{"title":"Aplicação","explanation":"Momento inicial de hesitação, rodeios e busca de direção externa, associado à incerteza diante de um grupo relativamente não estruturado.","example":"Exemplo teórico: em um grupo pouco estruturado, os participantes conversam superficialmente e perguntam quem dará as orientações. Isso ilustra os rodeios iniciais descritos por Rogers."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":26,"section":"Rogers — processo grupal","topic":"Resistência à expressão pessoal","question":"Cena: no começo, estudantes evitam se expor pessoalmente e respondem com hostilidade ou reserva. Os diários abrem uma forma alternativa de expressão sem exigir revelação pública.\n\nComo a resistência à expressão pessoal pode aparecer no filme?","options":[],"answer":null,"explanation":"A reserva e a hostilidade podem funcionar como proteção diante de um ambiente percebido como inseguro. A confiança se constrói sem forçar a exposição.","points":[{"title":"Conceito","explanation":"Participantes podem se proteger com frases genéricas, ironia ou recusa de exposição. A resistência precisa ser compreendida no contexto e não tratada automaticamente como desobediência.","example":""},{"title":"Aplicação","explanation":"A reserva e a hostilidade podem funcionar como proteção diante de um ambiente percebido como inseguro. A confiança se constrói sem forçar a exposição.","example":"Cena: no começo, estudantes evitam se expor pessoalmente e respondem com hostilidade ou reserva. Os diários abrem uma forma alternativa de expressão sem exigir revelação pública."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":27,"section":"Rogers — processo grupal","topic":"Sentimentos negativos e conflito no aqui-agora","question":"Cena: Eva termina a leitura do diário de Anne Frank e questiona Erin, revoltada com a morte da personagem. A reação dá lugar a uma conversa com a turma sobre a história.\n\nQual processo rogeriano aparece na revolta de Eva?","options":[],"answer":null,"explanation":"Expressão de sentimentos negativos no aqui-agora, inclusive dirigidos à facilitadora. A manifestação pode ser acolhida e elaborada sem retaliação.","points":[{"title":"Conceito","explanation":"Com maior expressão, podem emergir críticas e sentimentos negativos, inclusive contra o facilitador. Acolher a manifestação com responsabilidade não significa extinguir divergências por obrigação.","example":""},{"title":"Aplicação","explanation":"Expressão de sentimentos negativos no aqui-agora, inclusive dirigidos à facilitadora. A manifestação pode ser acolhida e elaborada sem retaliação.","example":"Cena: Eva termina a leitura do diário de Anne Frank e questiona Erin, revoltada com a morte da personagem. A reação dá lugar a uma conversa com a turma sobre a história."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":28,"section":"Rogers — processo grupal","topic":"Estalar das fachadas e autenticidade crescente","question":"Cena: no brinde à mudança, um aluno compartilha o relato de que perdeu a moradia e teve vergonha de voltar à escola. Revela uma vulnerabilidade antes escondida.\n\nComo essa cena ilustra o estalar das fachadas?","options":[],"answer":null,"explanation":"A segurança relacional permite reduzir defesas e apresentar experiências pessoais que antes eram ocultadas. O grupo passa a conhecer a pessoa além de sua imagem defensiva.","points":[{"title":"Conceito","explanation":"Rogers descreve redução de máscaras sociais defensivas, com manifestações mais genuínas de necessidades, fragilidades e afetos quando a segurança relacional aumenta.","example":""},{"title":"Aplicação","explanation":"A segurança relacional permite reduzir defesas e apresentar experiências pessoais que antes eram ocultadas. O grupo passa a conhecer a pessoa além de sua imagem defensiva.","example":"Cena: no brinde à mudança, um aluno compartilha o relato de que perdeu a moradia e teve vergonha de voltar à escola. Revela uma vulnerabilidade antes escondida."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":29,"section":"Rogers — processo grupal","topic":"Feedback interpessoal","question":"Cena: na discussão sobre a morte de Anne Frank, outros alunos apresentam a Eva maneiras diferentes de compreender a história. Isso permite pensar o retorno interpessoal; o feedback rogeriano propriamente dito comunica como a interação afeta quem fala.\n\nComo diferenciar feedback de opinião genérica sobre alguém?","options":[],"answer":null,"explanation":"Feedback envolve comunicar percepções e efeitos da interação a partir da própria experiência, oferecendo ao outro oportunidade de compreender e responder.","points":[{"title":"Conceito","explanation":"Feedback se refere a comunicar como se percebe a interação e como se é afetado pelo outro, no aqui-agora, com cuidado e abertura à resposta. Não é sentença sobre a personalidade.","example":""},{"title":"Aplicação","explanation":"Feedback envolve comunicar percepções e efeitos da interação a partir da própria experiência, oferecendo ao outro oportunidade de compreender e responder.","example":"Cena: na discussão sobre a morte de Anne Frank, outros alunos apresentam a Eva maneiras diferentes de compreender a história. Isso permite pensar o retorno interpessoal; o feedback rogeriano propriamente dito comunica como a interação afeta quem fala."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":30,"section":"Rogers — processo grupal","topic":"Confrontação responsável","question":"Cena: Erin interrompe a circulação da caricatura racista e questiona seus efeitos. A conduta discriminatória é confrontada sem afirmar que o estudante perdeu seu valor como pessoa.\n\nComo essa cena pode ser lida à luz da confrontação responsável?","options":[],"answer":null,"explanation":"Uma conduta ou discrepância pode ser questionada sem desqualificar a pessoa. A confrontação rogeriana envolve comunicação direta com respeito e abertura à compreensão.","points":[{"title":"Conceito","explanation":"Confrontar não é atacar: pode significar expor discrepância percebida entre fala e ação sem desqualificar a pessoa. O valor da pessoa permanece, mesmo quando uma conduta é questionada.","example":""},{"title":"Aplicação","explanation":"Uma conduta ou discrepância pode ser questionada sem desqualificar a pessoa. A confrontação rogeriana envolve comunicação direta com respeito e abertura à compreensão.","example":"Cena: Erin interrompe a circulação da caricatura racista e questiona seus efeitos. A conduta discriminatória é confrontada sem afirmar que o estudante perdeu seu valor como pessoa."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":31,"section":"Rogers — processo grupal","topic":"Capacidade de ajuda entre membros","question":"Cena: após as discussões sobre Anne Frank, os estudantes trabalham juntos para viabilizar a visita de Miep Gies. É um exemplo de cooperação que deixa de depender apenas da iniciativa de Erin.\n\nO que significa capacidade de ajuda entre os membros?","options":[],"answer":null,"explanation":"Os participantes passam a oferecer apoio e compreensão entre si, em vez de depender exclusivamente do facilitador. Cooperação pedagógica é uma aproximação, não prova de efeito terapêutico.","points":[{"title":"Conceito","explanation":"Com maior confiança, o apoio e a compreensão deixam de depender exclusivamente do facilitador. Participantes podem ajudar uns aos outros a elaborar experiências e testar novas formas de se relacionar.","example":""},{"title":"Aplicação","explanation":"Os participantes passam a oferecer apoio e compreensão entre si, em vez de depender exclusivamente do facilitador. Cooperação pedagógica é uma aproximação, não prova de efeito terapêutico.","example":"Cena: após as discussões sobre Anne Frank, os estudantes trabalham juntos para viabilizar a visita de Miep Gies. É um exemplo de cooperação que deixa de depender apenas da iniciativa de Erin."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":32,"section":"Rogers — processo grupal","topic":"Sentimentos positivos e intimidade grupal","question":"Cena: ao saberem que poderão permanecer com Erin nos anos seguintes, os alunos manifestam alegria e afeto. Isso contrasta com a hostilidade que predominava no início.\n\nComo sentimentos positivos podem indicar transformação das relações?","options":[],"answer":null,"explanation":"Expressões de afeto, confiança e apreço podem acompanhar a aproximação e a intimidade grupal. Não significam ausência definitiva de conflitos.","points":[{"title":"Conceito","explanation":"O reconhecimento, o apoio e os sentimentos positivos podem ganhar espaço depois que conflitos são expressos e elaborados; a intimidade não precisa ser fabricada nem igual para todos.","example":""},{"title":"Aplicação","explanation":"Expressões de afeto, confiança e apreço podem acompanhar a aproximação e a intimidade grupal. Não significam ausência definitiva de conflitos.","example":"Cena: ao saberem que poderão permanecer com Erin nos anos seguintes, os alunos manifestam alegria e afeto. Isso contrasta com a hostilidade que predominava no início."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":33,"section":"Rogers — ética e facilitação","topic":"Facilitador: presença sem controle autoritário","question":"Cena: os alunos propõem convidar Miep Gies e arrecadar recursos. Erin apoia a iniciativa em vez de se colocar como única autora do projeto.\n\nComo a iniciativa de convidar Miep Gies ilustra facilitação e autonomia?","options":[],"answer":null,"explanation":"A facilitadora oferece condições para que o grupo desenvolva iniciativas próprias e participe das decisões. A professora continua responsável pela atividade escolar.","points":[{"title":"Conceito","explanation":"O facilitador oferece autenticidade, empatia e aceitação, favorece condições de diálogo e cuida do enquadre. Facilitar não é abandonar o grupo, impor interpretações ou deixar acontecer qualquer dano.","example":""},{"title":"Aplicação","explanation":"A facilitadora oferece condições para que o grupo desenvolva iniciativas próprias e participe das decisões. A professora continua responsável pela atividade escolar.","example":"Cena: os alunos propõem convidar Miep Gies e arrecadar recursos. Erin apoia a iniciativa em vez de se colocar como única autora do projeto."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":34,"section":"Rogers — ética e facilitação","topic":"Empatia não apaga diferenças sociais","question":"Cena: na dinâmica da linha, alunos de diferentes pertencimentos descobrem vivências compartilhadas. As semelhanças não eliminam as experiências particulares de racismo e desigualdade.\n\nPor que a compreensão empática não apaga diferenças sociais?","options":[],"answer":null,"explanation":"Compreender o outro exige atenção a seu referencial e contexto, sem presumir que sofrimentos semelhantes tornam todas as experiências iguais.","points":[{"title":"Conceito","explanation":"Reconhecer a singularidade de alguém não significa negar racismo, desigualdade, violência ou disputas de poder. A relação facilitadora precisa levar o contexto social em conta.","example":""},{"title":"Aplicação","explanation":"Compreender o outro exige atenção a seu referencial e contexto, sem presumir que sofrimentos semelhantes tornam todas as experiências iguais.","example":"Cena: na dinâmica da linha, alunos de diferentes pertencimentos descobrem vivências compartilhadas. As semelhanças não eliminam as experiências particulares de racismo e desigualdade."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":35,"section":"Filme — conexões para a prova","topic":"Escritores da Liberdade: subgrupos e transformação de papéis","question":"Cena: no início, os alunos se agrupam por pertencimentos e evitam aproximações. Ao longo do filme, passam a realizar projetos e construir uma identidade coletiva como escritores.\n\nComo Moreno e Rogers explicam dimensões diferentes dessa mudança?","options":[],"answer":null,"explanation":"Moreno destaca vínculos, papéis e possibilidades de novas respostas; Rogers destaca o clima facilitador, a expressão pessoal e o desenvolvimento de confiança.","points":[{"title":"Conceito","explanation":"No início do filme, estudantes se posicionam em subgrupos desconfiados. A compreensão moreniana destaca a rede de papéis e vínculos e a possibilidade de mudança; a rogeriana destaca condições de escuta e confiança.","example":""},{"title":"Aplicação","explanation":"Moreno destaca vínculos, papéis e possibilidades de novas respostas; Rogers destaca o clima facilitador, a expressão pessoal e o desenvolvimento de confiança.","example":"Cena: no início, os alunos se agrupam por pertencimentos e evitam aproximações. Ao longo do filme, passam a realizar projetos e construir uma identidade coletiva como escritores."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":36,"section":"Filme — conexões para a prova","topic":"Jogo da linha: reconhecimento, tele e empatia","question":"Cena: a professora marca uma linha no chão e propõe perguntas. Os participantes avançam quando se identificam com elas e reconhecem experiências comuns de perda.\n\nQuais duas aproximações teóricas são defensáveis no jogo da linha?","options":[],"answer":null,"explanation":"Moreno: mobilização grupal semelhante ao aquecimento e percepção recíproca. Rogers: condições para escuta, reconhecimento e compreensão. Não é teste sociométrico nem terapia formal.","points":[{"title":"Conceito","explanation":"Os estudantes se aproximam de uma linha conforme experiências relatadas. A cena pode ser interpretada como ampliação de percepção recíproca (tele, em aproximação) e de compreensão empática, sem execução técnica de sociometria.","example":""},{"title":"Aplicação","explanation":"Moreno: mobilização grupal semelhante ao aquecimento e percepção recíproca. Rogers: condições para escuta, reconhecimento e compreensão. Não é teste sociométrico nem terapia formal.","example":"Cena: a professora marca uma linha no chão e propõe perguntas. Os participantes avançam quando se identificam com elas e reconhecem experiências comuns de perda."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":37,"section":"Filme — conexões para a prova","topic":"Diários: escolha, confidencialidade e autenticidade","question":"Cena: os diários permitem escrever sobre vivências pessoais e escolher se serão lidos pela professora. Alguns estudantes passam posteriormente a compartilhar seus relatos.\n\nComo os diários articulam aceitação e redução de fachadas?","options":[],"answer":null,"explanation":"O respeito à escolha de compartilhar ajuda a criar segurança, favorecendo expressão autêntica. Não é necessário interpretar a escrita como psicoterapia.","points":[{"title":"Conceito","explanation":"A escrita oferece espaço para narrativa pessoal e possível redução de fachadas. A opção de compartilhar ou não é central para confiança e respeito à autonomia; não torna o exercício psicoterapia.","example":""},{"title":"Aplicação","explanation":"O respeito à escolha de compartilhar ajuda a criar segurança, favorecendo expressão autêntica. Não é necessário interpretar a escrita como psicoterapia.","example":"Cena: os diários permitem escrever sobre vivências pessoais e escolher se serão lidos pela professora. Alguns estudantes passam posteriormente a compartilhar seus relatos."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":38,"section":"Filme — conexões para a prova","topic":"Caricatura racista: aceitação com limites","question":"Cena: uma caricatura racista circula pela sala e Erin interrompe a humilhação. Ela utiliza o acontecimento para discutir preconceito e suas consequências.\n\nComo diferenciar acolher uma pessoa e aceitar uma agressão?","options":[],"answer":null,"explanation":"Rogers: consideração positiva preserva o valor da pessoa, mas não obriga a aprovar agressões. Moreno: padrões coletivos cristalizados podem ser examinados e transformados.","points":[{"title":"Conceito","explanation":"A professora enfrenta uma humilhação racial. A análise rogeriana permite diferenciar acolhimento da pessoa e rejeição da conduta; Moreno ajuda a refletir sobre papéis cristalizados e transformação das interações.","example":""},{"title":"Aplicação","explanation":"Rogers: consideração positiva preserva o valor da pessoa, mas não obriga a aprovar agressões. Moreno: padrões coletivos cristalizados podem ser examinados e transformados.","example":"Cena: uma caricatura racista circula pela sala e Erin interrompe a humilhação. Ela utiliza o acontecimento para discutir preconceito e suas consequências."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":39,"section":"Moreno — fundamentos","topic":"Matriz de identidade","question":"Exemplo teórico: o bebê se relaciona com figuras de cuidado antes de desenvolver uma diferenciação mais elaborada entre si e o outro. Não se pode reconstruir a matriz de identidade de Eva só por cenas do filme.\n\nO que é matriz de identidade?","options":[],"answer":null,"explanation":"É o contexto relacional inicial em que se formam os primeiros vínculos e modos de assumir papéis.","points":[{"title":"Conceito","explanation":"Contexto sociofamiliar inicial em que começam a se constituir vínculos, diferenciações e papéis.","example":""},{"title":"Aplicação","explanation":"É o contexto relacional inicial em que se formam os primeiros vínculos e modos de assumir papéis.","example":"Exemplo teórico: o bebê se relaciona com figuras de cuidado antes de desenvolver uma diferenciação mais elaborada entre si e o outro. Não se pode reconstruir a matriz de identidade de Eva só por cenas do filme."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":40,"section":"Moreno — fundamentos","topic":"Revolução criadora","question":"Cena: os estudantes passam da divisão por pertencimentos à produção coletiva de um livro. A transformação ilustra a possibilidade de superar padrões rígidos de ação, sem pressupor tratamento psicodramático.\n\nComo a produção do livro se aproxima da revolução criadora?","options":[],"answer":null,"explanation":"A turma constrói uma forma nova de atuar e se reconhecer, em vez de repetir apenas os papéis e relações anteriores.","points":[{"title":"Conceito","explanation":"Recuperação da espontaneidade e da criatividade diante de padrões cristalizados, permitindo novas respostas e relações.","example":""},{"title":"Aplicação","explanation":"A turma constrói uma forma nova de atuar e se reconhecer, em vez de repetir apenas os papéis e relações anteriores.","example":"Cena: os estudantes passam da divisão por pertencimentos à produção coletiva de um livro. A transformação ilustra a possibilidade de superar padrões rígidos de ação, sem pressupor tratamento psicodramático."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":41,"section":"Rogers — processo grupal","topic":"Exploração de material pessoal significativo","question":"Cena: os relatos dos diários tratam de perdas, violência, moradia e relações familiares, dando lugar à história particular dos estudantes.\n\nComo a escrita favorece a exploração de material pessoal?","options":[],"answer":null,"explanation":"Ela permite organizar e expressar experiências que possuem significado para quem escreve, respeitando o ritmo e a decisão de compartilhar.","points":[{"title":"Conceito","explanation":"Quando existe segurança suficiente, os membros podem abordar experiências importantes para sua própria vida, não apenas assuntos superficiais.","example":""},{"title":"Aplicação","explanation":"Ela permite organizar e expressar experiências que possuem significado para quem escreve, respeitando o ritmo e a decisão de compartilhar.","example":"Cena: os relatos dos diários tratam de perdas, violência, moradia e relações familiares, dando lugar à história particular dos estudantes."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":42,"section":"Rogers — processo grupal","topic":"Mudança de comportamento dentro e fora do grupo","question":"Cena: Marcus busca reconstruir a relação com a mãe. A transformação não fica restrita ao comportamento na escola.\n\nComo a trajetória de Marcus se relaciona à mudança fora do grupo?","options":[],"answer":null,"explanation":"Ela ilustra a possibilidade de experimentar novas formas de relação no cotidiano, além do espaço grupal, sem atribuir a mudança exclusivamente à professora.","points":[{"title":"Conceito","explanation":"Os encontros podem favorecer mudanças que se estendem às relações cotidianas, para além da interação imediata do grupo.","example":""},{"title":"Aplicação","explanation":"Ela ilustra a possibilidade de experimentar novas formas de relação no cotidiano, além do espaço grupal, sem atribuir a mudança exclusivamente à professora.","example":"Cena: Marcus busca reconstruir a relação com a mãe. A transformação não fica restrita ao comportamento na escola."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."},{"n":43,"section":"Filme — conexões para a prova","topic":"Miep Gies e a possibilidade de novas respostas","question":"Cena: Miep Gies descreve sua ajuda à família Frank e reconhece a capacidade dos estudantes de fazer diferença em suas próprias circunstâncias.\n\nComo relacionar o encontro com Miep Gies a Moreno?","options":[],"answer":null,"explanation":"A narrativa permite refletir sobre espontaneidade e criação de respostas diante de situações difíceis; não é uma dramatização conduzida pela professora.","points":[{"title":"Conceito","explanation":"A experiência narrada por Miep Gies permite discutir escolha, responsabilidade e a possibilidade de agir de maneira diferente diante de pressões coletivas.","example":""},{"title":"Aplicação","explanation":"A narrativa permite refletir sobre espontaneidade e criação de respostas diante de situações difíceis; não é uma dramatização conduzida pela professora.","example":"Cena: Miep Gies descreve sua ajuda à família Frank e reconhece a capacidade dos estudantes de fazer diferença em suas próprias circunstâncias."}],"contrast":"Organize a resposta em conceito, cena ou exemplo e explicação da relação. Quando a cena não reproduzir a técnica, apresente a relação como aproximação conceitual."}]};
const SOCIAL_P3_GUIDE={"id":"social-p3-revisao-integrada-2026","title":"Revisão comentada — Psicologia Social I (P3)","subtitle":"15 questões autorais para integração das perspectivas e temas contemporâneos","source":"Revisão autoral baseada em materiais de Psicologia Social I cadastrados no site: Martín-Baró, Psicologia Sócio-Histórica, identidade, representações sociais, preconceito, interseccionalidade, epistemicídio, infância/políticas públicas e tecnologias digitais. O plano disponível no acervo tem dados divergentes de turma/semestre e não comprova sozinho o recorte da P3. O roteiro não é oficial e os conteúdos exatos devem ser confirmados com o professor.","status":"adaptado","questions":[{"n":1,"section":"Integração das perspectivas","topic":"Paradigmas de Psicologia Social","question":"Compara as perspectivas sociológica, psicológica, sócio-histórica e crítica na compreensão de um fenômeno coletivo.","explanation":"As perspectivas diferem quanto às perguntas e escalas de análise. Uma abordagem sociológica pode enfatizar representações, instituições e relações sociais; a psicológica pode examinar processos de categorização e atitudes; a sócio-histórica considera a constituição histórica e material dos sujeitos; a crítica problematiza poder, desigualdades e produção ideológica. Ao analisar uma situação concreta, é preciso explicitar o referencial usado em vez de misturar conceitos sem critério.","contrast":"Não reduzir todas as abordagens a uma mesma definição do indivíduo. A perspectiva adotada orienta o que conta como problema, evidência e possibilidade de intervenção.","options":[],"answer":null},{"n":2,"section":"Identidade e representação","topic":"Identidade em Stuart Hall","question":"Como Stuart Hall ajuda a compreender identidade e diferenças nas sociedades contemporâneas?","explanation":"A identidade não é compreendida como uma essência estável e imune a mudanças históricas. Em sociedades marcadas por transformações culturais e relações de poder, pertencimentos e posições de sujeito podem se deslocar e ser construídos nas relações sociais. Uma pessoa pode vivenciar identificações múltiplas, por vezes contraditórias, conforme os contextos. Esse olhar ajuda a analisar conflitos de pertencimento sem reduzir identidades a características individuais fixas.","contrast":"Não interpretar multiplicidade de identificações como doença ou ausência de identidade. Trata-se de uma reflexão sociocultural sobre constituição dos sujeitos.","options":[],"answer":null},{"n":3,"section":"Identidade e representação","topic":"Representações sociais","question":"O que são representações sociais e como podem ser observadas em narrativas coletivas, como no filme Narradores de Javé?","explanation":"Representações sociais são formas compartilhadas e socialmente elaboradas de compreender objetos, acontecimentos e grupos. Circulam na comunicação e nas práticas cotidianas, tornando temas familiares e orientando percepções. No caso de narrativas sobre a história de uma comunidade, versões e disputas por reconhecimento podem expressar interesses e posições sociais diferentes. A análise observa como sentidos são produzidos, legitimados e contestados.","contrast":"Não confundir representação social com opinião privada de uma única pessoa ou com cópia transparente da realidade. É necessário observar circulação, ancoragens e contextos.","options":[],"answer":null},{"n":4,"section":"Identidade e representação","topic":"Estigma e preconceito","question":"Diferencia estereótipo, preconceito, discriminação e estigma em uma situação de exclusão social.","explanation":"Estereótipos são generalizações atribuídas a pessoas ou grupos; preconceitos envolvem avaliações e atitudes frequentemente negativas; discriminação refere-se a práticas de tratamento desigual; estigma designa processos de desvalorização social de atributos e identidades em relações específicas. Esses processos podem ocorrer conjuntamente, mas não são sinônimos. A Psicologia Social investiga como se sustentam em normas e instituições, além de experiências individuais.","contrast":"Não supor que todo estereótipo leva à mesma ação nem restringir o preconceito a uma opinião isolada: relações estruturais e consequências concretas importam.","options":[],"answer":null},{"n":5,"section":"Psicologia sócio-histórica e crítica","topic":"Sujeito e condições históricas","question":"Como a Psicologia Sócio-Histórica relaciona constituição da subjetividade, trabalho e condições materiais de vida?","explanation":"A subjetividade é compreendida como constituída em processos históricos e sociais, envolvendo linguagem, relações de trabalho, instituições e contradições das condições materiais. Experiências aparentemente pessoais podem ter mediações coletivas e políticas. A análise busca compreender processos concretos sem apagar a agência do sujeito. Isso permite questionar explicações que atribuem desigualdades apenas a mérito, esforço individual ou características naturais.","contrast":"Não tratar a pessoa como simples reflexo passivo do contexto. A relação entre sujeito e sociedade envolve atividade, contradições e transformação.","options":[],"answer":null},{"n":6,"section":"Psicologia sócio-histórica e crítica","topic":"Psicologia da Libertação","question":"Quais são os objetivos da Psicologia da Libertação de Ignacio Martín-Baró e como ela problematiza a atuação profissional?","explanation":"A proposta de Martín-Baró exige que a Psicologia considere a realidade histórica das populações latino-americanas, suas lutas e a produção social do sofrimento. A atuação é chamada a questionar explicações que legitimam opressões e a contribuir com processos de conscientização, participação e transformação social. O conhecimento psicológico não é neutro em relação a valores e interesses, exigindo posicionamento ético refletido e diálogo com experiências concretas.","contrast":"Não confundir Psicologia da Libertação com propaganda ou mera defesa de opinião pessoal. Ela demanda investigação rigorosa de realidade, relações de poder e condições de vida.","options":[],"answer":null},{"n":7,"section":"Psicologia sócio-histórica e crítica","topic":"Democracia formal e efetiva","question":"Diferencia democracia formal e democracia efetiva no contexto da análise de Martín-Baró.","explanation":"A democracia formal refere-se à existência de regras, instituições, eleições e direitos reconhecidos juridicamente. A democracia efetiva exige condições concretas para o exercício desses direitos e participação na vida social. Quando desigualdades materiais, violência ou exclusão impedem o acesso a direitos, pode haver distância entre promessa institucional e experiência cotidiana. A análise psicossocial considera estruturas e processos subjetivos que sustentam essa distância.","contrast":"Não concluir que eleições ou normas jurídicas são irrelevantes; a distinção aponta que a existência formal de direitos não garante, por si, seu exercício real.","options":[],"answer":null},{"n":8,"section":"Psicologia sócio-histórica e crítica","topic":"Fatalismo latino-americano","question":"O que Martín-Baró entende por fatalismo latino-americano e por que não se deve reduzi-lo a traço de personalidade?","explanation":"O fatalismo envolve formas de compreender o destino social como inevitável, podendo favorecer resignação diante de adversidades. Na perspectiva crítica, ele deve ser situado em condições históricas de dominação e desigualdade e na construção de sentidos que desestimulam a ação coletiva. Não é uma característica natural do povo latino-americano. Intervenções exigem reconhecer possibilidades reais de ação, barreiras concretas e experiência dos grupos envolvidos.","contrast":"Não culpar populações em situação de desigualdade por suas condições. Uma explicação somente psicológica pode ocultar relações estruturais que limitam escolhas.","options":[],"answer":null},{"n":9,"section":"Psicologia sócio-histórica e crítica","topic":"Desideologização","question":"O que significa desideologização na Psicologia Social e como ela se diferencia da simples correção de informações falsas?","explanation":"Desideologização busca tornar visíveis relações entre discursos, interesses, condições sociais e modos naturalizados de explicar a realidade. Envolve examinar como certos sentidos legitimam injustiças e impedem compreender alternativas de ação. Não se limita a apontar erros factuais: inclui investigar quem produz mensagens, como circulam e quais efeitos têm nas práticas e relações de poder. O trabalho requer diálogo crítico e valorização da experiência concreta.","contrast":"Não apresentar desideologização como impor uma verdade pronta a outras pessoas. O processo exige reflexão, evidências e participação.","options":[],"answer":null},{"n":10,"section":"Marcadores sociais e diferenças","topic":"Interseccionalidade","question":"Como a interseccionalidade pode aprofundar a análise de desigualdades de raça, gênero e classe?","explanation":"A interseccionalidade considera que diferentes relações de poder se articulam e podem produzir experiências específicas que não são explicadas pela simples soma de categorias isoladas. Uma situação de exclusão no trabalho, por exemplo, pode envolver gênero, raça, classe e condições migratórias de formas inseparáveis. O pesquisador precisa observar a posição concreta de sujeitos e instituições em vez de usar marcadores como rótulos automáticos.","contrast":"Não tratar identidades como causas inevitáveis de comportamento. Marcadores são relevantes conforme história, contexto e relações de poder.","options":[],"answer":null},{"n":11,"section":"Marcadores sociais e diferenças","topic":"Epistemicídio","question":"O que é epistemicídio e qual sua relação com racismo, sexismo e produção do conhecimento?","explanation":"Epistemicídio descreve processos de silenciamento, deslegitimação ou destruição de saberes e modos de conhecer de grupos historicamente subordinados. Em uma análise crítica, pode ocorrer quando instituições tratam certas tradições e sujeitos como incapazes de produzir conhecimento válido, reproduzindo hierarquias coloniais e de gênero. Investigar suas formas exige analisar critérios de legitimidade, circulação de autores e vozes ausentes nos currículos.","contrast":"Não basta citar diversidade superficialmente: é preciso examinar como instituições estabelecem autoridade, acesso e reconhecimento de conhecimentos.","options":[],"answer":null},{"n":12,"section":"Marcadores sociais e diferenças","topic":"Infância e políticas públicas","question":"Como políticas públicas podem influenciar a produção social das experiências de infância e juventude?","explanation":"As experiências de crianças e jovens são atravessadas por condições de moradia, educação, saúde, proteção, raça, gênero e território. Políticas públicas podem ampliar direitos e recursos, mas sua implementação desigual pode reproduzir exclusões. A Psicologia Social investiga como instituições definem problemas, classificam populações e produzem efeitos nas trajetórias, sem reduzir a infância a uma etapa abstrata e igual para todos.","contrast":"Não inferir que todas as crianças em um mesmo grupo social vivem experiências idênticas, nem explicar desigualdades apenas por escolhas familiares.","options":[],"answer":null},{"n":13,"section":"Tecnologias da informação","topic":"Algoritmos e subjetividade","question":"Como algoritmos de recomendação e plataformas digitais podem influenciar formas de participação, percepção social e polarização?","explanation":"Sistemas de recomendação selecionam e ordenam conteúdos conforme objetivos de plataforma e sinais de interação, podendo ampliar a exposição repetida a certos temas e perspectivas. Isso pode interagir com vieses, identidades, redes de pertencimento e disputas políticas, mas não elimina a ação das pessoas. Uma análise psicossocial investiga interesses econômicos, circulação de mensagens, efeitos da infraestrutura e práticas concretas de uso.","contrast":"Não afirmar que todo algoritmo cria automaticamente uma bolha fechada nem que as pessoas perdem completamente autonomia. Efeitos dependem do desenho da plataforma e do contexto.","options":[],"answer":null},{"n":14,"section":"Integração crítica da P3","topic":"Observação e evidências","question":"Como relacionar uma observação de campo a conceitos da Psicologia Social sem transformar impressões em conclusões generalizantes?","explanation":"É necessário delimitar problema e contexto, explicitar o procedimento de observação e distinguir episódios registrados de hipóteses interpretativas. Depois, conceitos como identidade, representação, ideologia e marcadores sociais podem ajudar a problematizar o fenômeno, desde que as relações sejam justificadas. Limites da amostra, possíveis vieses e implicações éticas devem ser reconhecidos. Uma narrativa teoricamente coerente não substitui evidência empírica suficiente.","contrast":"Não apresentar casos isolados como prova universal nem tratar a escolha de um referencial como autorização para ignorar dados discordantes.","options":[],"answer":null},{"n":15,"section":"Integração crítica da P3","topic":"Caso de desigualdade e comunicação","question":"Uma campanha digital responsabiliza indivíduos isoladamente por problemas estruturais. Como integrar fatalismo, ideologia e processos de comunicação na análise?","explanation":"Pode-se investigar quais causas são omitidas, como a campanha constrói responsabilidade e que possibilidades de ação apresenta às pessoas atingidas. Martín-Baró ajuda a pensar naturalização da desigualdade e fatalismo; a análise das plataformas observa alcance, repetição e segmentação; perspectivas de interseccionalidade ajudam a considerar impactos distintos. O objetivo é formular hipóteses sustentadas em dados e identificar tensões entre explicações individuais e condições sociais.","contrast":"Não pressupor automaticamente a intenção de todos os envolvidos ou efeitos iguais entre públicos. A análise exige evidências, atenção ao contexto e cuidado com simplificações.","options":[],"answer":null}]};
const AVALIACAO_P3_GUIDE={"id":"avaliacao-p3-revisao-conferida-2026","title":"Revisão comentada — Avaliação Psicológica (P3)","subtitle":"15 questões autorais de devolutiva, contextos de atuação e ética","source":"Revisão autoral delimitada pelo cronograma da turma 357/2026-02 da professora Maísa dos Santos Rigoni: após a P2 de 29/10, constam devolutiva (03/11), contexto organizacional (05/11), hospitalar (10/11), forense (12/11), pacientes trans (17/11), ética (19/11) e palestra COF (24/11), com P3 em 26/11. Não é estudo dirigido oficial nem gabarito docente. Materiais das palestras ainda podem precisar de complementação.","status":"adaptado","questions":[{"n":1,"section":"Entrevista de devolução","topic":"Objetivos da devolutiva","question":"Qual é a finalidade da entrevista de devolução em um processo de avaliação psicológica e o que a diferencia de uma simples entrega de resultados?","explanation":"A devolutiva procura comunicar e contextualizar os achados de maneira compreensível, acolhendo dúvidas e relacionando informações à demanda inicial e às condições da pessoa avaliada. É uma etapa de diálogo que pode orientar encaminhamentos e cuidados, não apenas uma leitura de escores ou entrega de documentos. A comunicação deve deixar claros os limites dos dados, evitar rótulos e respeitar a autonomia, a compreensão e as necessidades da pessoa.","contrast":"Não reduzir a entrevista a uma comunicação unilateral ou a uma listagem de resultados. É preciso verificar compreensão e evitar conclusões que ultrapassem o alcance da avaliação.","options":[],"answer":null},{"n":2,"section":"Entrevista de devolução","topic":"Comunicação acessível","question":"Uma pessoa recebe resultados psicológicos com termos técnicos que não compreende. Como o profissional pode reorganizar a devolutiva?","explanation":"O psicólogo pode começar pela pergunta que motivou a avaliação, traduzir termos técnicos em linguagem acessível, utilizar exemplos pertinentes e oferecer espaço para a pessoa expressar dúvidas e reações. Também precisa distinguir resultados de hipóteses e explicar limitações e recomendações proporcionais. Adaptar linguagem não significa simplificar indevidamente os achados; significa torná-los compreensíveis no contexto de vida de quem os recebe.","contrast":"Evitar termos alarmistas ou diagnósticos sem fundamentação. Também não basta perguntar 'entendeu?' sem oferecer condições reais para compreensão.","options":[],"answer":null},{"n":3,"section":"Entrevista de devolução","topic":"Acolhimento de reações","question":"Uma pessoa discorda de parte dos resultados e se emociona durante a devolutiva. Que atitudes são adequadas?","explanation":"Reações de surpresa, dúvida ou sofrimento podem surgir diante de informações sobre si. É importante acolher sem invalidar, escutar a perspectiva da pessoa, explicar os critérios do processo e considerar se há aspectos que exigem esclarecimento. O profissional deve preservar um espaço dialógico e não usar a autoridade técnica para impedir perguntas. Eventuais orientações de cuidado precisam respeitar os limites do processo e as necessidades concretas da pessoa avaliada.","contrast":"Não transformar discordância em resistência patológica nem utilizar a devolutiva para impor uma interpretação única. O diálogo pode enriquecer a contextualização dos resultados.","options":[],"answer":null},{"n":4,"section":"Entrevista de devolução","topic":"Informação e confidencialidade","question":"Como lidar com o pedido de terceiros para receber informações detalhadas de uma devolutiva psicológica?","explanation":"A comunicação de resultados deve respeitar finalidade, consentimento e limites de confidencialidade, além das condições legais e profissionais aplicáveis. É essencial verificar quem solicita a informação, qual seu papel e qual conteúdo é necessário compartilhar. O cuidado ético pode exigir comunicações distintas conforme se trate de pessoa avaliada, responsável legal ou instituição solicitante, sempre evitando exposição de informações desnecessárias.","contrast":"Não presumir que familiares, gestores ou instituições tenham acesso irrestrito ao conteúdo da avaliação. Direitos da pessoa avaliada e regras profissionais orientam o compartilhamento.","options":[],"answer":null},{"n":5,"section":"Avaliação em contexto organizacional","topic":"Finalidades e contexto","question":"Que tipos de demanda podem levar à avaliação psicológica em uma organização e quais cuidados a diferenciam da avaliação clínica?","explanation":"No âmbito organizacional, avaliações podem ser solicitadas para seleção, orientação ou desenvolvimento profissional, conforme finalidade e normas aplicáveis. O psicólogo precisa delimitar a demanda, usar procedimentos pertinentes e comunicar conclusões proporcionais à função solicitada. A análise deve considerar aspectos do trabalho, condições organizacionais e riscos de discriminação, sem converter dados de avaliação em julgamentos globais da pessoa.","contrast":"Não transpor automaticamente conclusões de um contexto clínico para decisões sobre emprego. Um resultado não deve ser usado fora da finalidade para a qual foi obtido.","options":[],"answer":null},{"n":6,"section":"Avaliação em contexto organizacional","topic":"Sigilo e uso de dados","question":"Uma empresa pede acesso integral às respostas e informações íntimas de candidatos após uma avaliação. Como proceder?","explanation":"Deve-se examinar a finalidade legítima da solicitação, os limites da informação necessária para a decisão e as exigências éticas de confidencialidade. A pessoa avaliada não perde seus direitos de privacidade por estar em processo seletivo. A comunicação profissional deve se restringir ao que é pertinente e autorizado pelo enquadre e pelas normas, evitando exposição de dados sensíveis e uso discriminatório.","contrast":"Não entregar dados íntimos apenas porque a organização contratou o serviço. O vínculo contratual não elimina obrigações éticas para com a pessoa avaliada.","options":[],"answer":null},{"n":7,"section":"Avaliação no contexto hospitalar","topic":"Condições de hospitalização","question":"Como a avaliação psicológica no hospital pode adaptar procedimentos às condições clínicas e ao ambiente de cuidado?","explanation":"O ambiente hospitalar apresenta variações de tempo disponível, condições físicas, presença de familiares e prioridades clínicas. O psicólogo precisa delimitar a pergunta de avaliação, considerar estado de saúde, fadiga, medicamentos, compreensão e privacidade e relacionar informações pertinentes com a equipe. O planejamento é flexível, mas mantém fundamentação e respeito à autonomia, sem aplicar instrumentos indiscriminadamente quando a condição da pessoa não permite.","contrast":"Não confundir dificuldades decorrentes de doença, dor ou exaustão com características psicológicas permanentes. As condições do exame influenciam a interpretação.","options":[],"answer":null},{"n":8,"section":"Avaliação no contexto hospitalar","topic":"Equipe multiprofissional","question":"Que cuidados orientam o compartilhamento de informações psicológicas com outros profissionais de uma equipe de saúde?","explanation":"O trabalho multiprofissional exige comunicação suficiente para o cuidado, mas não compartilhamento irrestrito. O psicólogo considera finalidade, sigilo, necessidade clínica e compreensão da pessoa atendida, registrando informações de forma apropriada. Questões emocionais podem estar relacionadas à adesão, à comunicação e às redes de apoio, devendo ser situadas no contexto do adoecimento e da organização do cuidado.","contrast":"Não tratar a equipe como autorização genérica para divulgar histórias íntimas. Deve-se compartilhar apenas o necessário para ações de cuidado apropriadas.","options":[],"answer":null},{"n":9,"section":"Avaliação psicológica no contexto forense","topic":"Finalidade e delimitação","question":"Por que a avaliação psicológica forense exige cuidado especial com demanda, finalidade e limites das conclusões?","explanation":"No contexto forense, a avaliação responde a questões definidas em um procedimento ou solicitação jurídica e pode produzir efeitos sobre direitos e decisões institucionais. O profissional deve delimitar suas atribuições, utilizar informações pertinentes, distinguir dados de hipóteses e comunicar limites. A função avaliativa não é idêntica à relação terapêutica, e expectativas de sigilo e destinatários precisam ser explicados no enquadre.","contrast":"Não confundir o papel do avaliador com o de terapeuta, juiz ou advogado. A Psicologia oferece informações técnicas, não decide sozinha questões jurídicas.","options":[],"answer":null},{"n":10,"section":"Avaliação psicológica no contexto forense","topic":"Entrevistas e fontes","question":"Quais são os riscos de concluir algo em uma avaliação forense a partir de uma única declaração ou observação isolada?","explanation":"Uma informação isolada pode estar incompleta, ser influenciada por contexto, memória, expectativas ou finalidade do procedimento. A avaliação precisa de critérios técnicos, integração de fontes pertinentes e explicitação das limitações de cada evidência. Quando informações são divergentes, o profissional deve relatar de forma responsável a diferença observada, sem inventar certeza ou antecipar juízo que não possa fundamentar.","contrast":"Não usar um teste ou entrevista como detector automático de verdade e mentira. Limitações metodológicas precisam ser consideradas em qualquer conclusão.","options":[],"answer":null},{"n":11,"section":"Avaliação de pessoas trans","topic":"Acolhimento não patologizante","question":"Que princípios devem orientar a avaliação psicológica de pessoas trans?","explanation":"A avaliação precisa respeitar identidade de gênero, nome social, autonomia, história e demanda apresentada, sem supor que ser trans constitui transtorno mental. É fundamental considerar contexto de vida, barreiras de acesso, experiências de discriminação e necessidades reais de cuidado. Procedimentos e comunicação devem ser apropriados à finalidade e livres de estereótipos, com consentimento e respeito à privacidade.","contrast":"Não buscar 'provar' ou invalidar uma identidade de gênero por critérios pessoais do profissional. A atuação deve seguir normas éticas e técnicas aplicáveis.","options":[],"answer":null},{"n":12,"section":"Avaliação de pessoas trans","topic":"Demandas e diversidade","question":"Uma pessoa trans procura atendimento e relata ansiedade relacionada à rejeição familiar. Como evitar uma interpretação inadequada na avaliação?","explanation":"O profissional deve distinguir a identidade da pessoa das situações de sofrimento que relata. Pode investigar experiências de rejeição, ameaças, redes de apoio, condições materiais e sintomas apresentados, sem inferir causalidade automática ou reduzir toda demanda à identidade de gênero. A avaliação considera singularidades e proteção, com encaminhamentos proporcionais e diálogo sobre prioridades e objetivos.","contrast":"Não atribuir sofrimento inerente à condição trans nem ignorar a contribuição da discriminação e do contexto social. Identidade e demanda clínica não são sinônimos.","options":[],"answer":null},{"n":13,"section":"Ética e responsabilidade profissional","topic":"Consentimento e limites","question":"Quais cuidados éticos devem ser explicitados antes de uma avaliação psicológica em contextos diferentes?","explanation":"É importante apresentar finalidade, procedimentos, uso das informações, destinatários, limites da confidencialidade e possíveis consequências da avaliação com linguagem compreensível. O enquadre precisa considerar a autonomia e condições específicas da pessoa, além das obrigações institucionais e legais. Em contextos organizacionais, hospitalares e forenses, a clareza sobre papéis e destinatários é especialmente relevante.","contrast":"Não presumir que um mesmo termo de consentimento resolva todas as situações. O profissional deve adaptar a comunicação à demanda e às regras aplicáveis.","options":[],"answer":null},{"n":14,"section":"Ética e responsabilidade profissional","topic":"Limites da competência","question":"Uma instituição solicita que o psicólogo produza conclusões fora da sua competência e sem dados suficientes. Como deveria responder?","explanation":"O psicólogo precisa delimitar o que pode ser inferido tecnicamente com base nos procedimentos realizados e comunicar limites de maneira clara. Uma demanda institucional não autoriza especulações, uso inadequado de instrumentos ou afirmações sem respaldo. Quando necessário, pode propor outras fontes, encaminhamentos ou recusar conclusões incompatíveis com evidências e atribuições profissionais. A responsabilidade ética permanece mesmo diante de pressões externas.","contrast":"Não produzir laudos categóricos para satisfazer a instituição, nem confundir opinião pessoal com resultado de avaliação fundamentada.","options":[],"answer":null},{"n":15,"section":"Questão integradora da P3","topic":"Caso ético em contextos distintos","question":"Compara como a mesma preocupação com privacidade se manifesta na devolutiva, em uma empresa, no hospital e em uma avaliação forense.","explanation":"Em todos os contextos, devem ser respeitados direitos da pessoa avaliada, finalidade da avaliação e limites de confidencialidade. Na devolutiva, importa comunicar resultados de modo compreensível; na empresa, restringir a informação relevante à decisão; no hospital, compartilhar com a equipe apenas o necessário ao cuidado; no forense, explicar destinatários e responsabilidades específicas do procedimento. A análise ética depende do enquadre e das normas vigentes em cada contexto.","contrast":"Não existe autorização universal para divulgação integral dos dados. A mesma regra geral de proteção se concretiza de modos diferentes conforme demanda, vínculo e finalidade.","options":[],"answer":null}]};
function apply(db){
 const guides=window.PSICO_GUIDES||(window.PSICO_GUIDES={});
 guides.familia=guides.familia||[];
 if(!guides.familia.some(g=>g.id===FAMILY_P2_GUIDE.id))guides.familia.unshift(FAMILY_P2_GUIDE);
 guides.grupos=guides.grupos||[];
 if(!guides.grupos.some(g=>g.id===GRUPOS_P2_GUIDE.id))guides.grupos.unshift(GRUPOS_P2_GUIDE);
 guides.social=guides.social||[];
 const socialTopics=window.PSICO_FINAL_EXAMS?.curated?.(db,'social')||[];
 const socialNew=socialTopics.filter(t=>t.source);
 const socialQuestions=socialNew.map((t,i)=>({...makeQuestion(t,i),n:SOCIAL_P3_GUIDE.questions.length+i+1,section:'Raça, subjetividade e colonialismo digital',explanation:t.definition+'\n\nAplicação: '+t.scenario+'\n\nFonte: '+t.source,contrast:t.myth}));
 const refreshedSocial={...SOCIAL_P3_GUIDE,subtitle:(SOCIAL_P3_GUIDE.questions.length+socialQuestions.length)+' questões autorais — conteúdos desde a semana 9',source:SOCIAL_P3_GUIDE.source+' Complementado com Raça, ideologia e subjetividade; Subjetividade como expressão das relações sociais; Colonialismo Digital (capítulos 1 e 2).',questions:[...SOCIAL_P3_GUIDE.questions,...socialQuestions]};
 guides.social=guides.social.filter(g=>g.id!==SOCIAL_P3_GUIDE.id);
 guides.social.unshift(refreshedSocial);
 const newTextGuide=guides.social.find(g=>g.id==='social-novos-textos-2026');
 if(newTextGuide&&socialTopics.length){newTextGuide.questions=socialTopics.map(makeQuestion);newTextGuide.subtitle=socialTopics.length+' conceitos comentados e aplicados';newTextGuide.source='Revisão autoral baseada nos textos e slides da disciplina, incluindo os três materiais novos.';}
 guides.avaliacao=guides.avaliacao||[];
 if(!guides.avaliacao.some(g=>g.id===AVALIACAO_P3_GUIDE.id))guides.avaliacao.unshift(AVALIACAO_P3_GUIDE);
 const curated=window.PSICO_FINAL_EXAMS?.curated;
 if(typeof curated!=='function'||!db?.topics)return;
 for(const subject of TARGETS){
  const id='final-2026-2-'+subject;
  const topics=curated(db,subject);
  if(!topics?.length)continue;
  guides[subject]=guides[subject]||[];
  if(subject==='meta'||subject==='social')guides[subject]=guides[subject].filter(x=>x.id!==id);
  if(guides[subject].some(x=>x.id===id))continue;
  guides[subject].unshift({id,title:'Estudo dirigido — revisão final de 2026/2',
   subtitle:topics.length+' conceitos comentados com exemplos e limites de interpretação',
   source:'Roteiro didático autoral organizado com base nos tópicos dos materiais cadastrados na disciplina. Não reproduz literalmente um estudo dirigido do professor nem substitui a leitura dos arquivos.',
   status:'adaptado',questions:topics.map(makeQuestion)});
 }
}
window.PSICO_FINAL_GUIDES={apply,makeQuestion};
})();